"use client";

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Badge } from '@/components/ui/badge';
import { Separator } from '@/components/ui/separator';
import { useCurrentUser, useUsers } from '@/lib/hooks';
import { User, Plus, Users, Settings, LogOut, Eye, Trash2 } from 'lucide-react';

export function AdminPanel() {
  const [newUser, setNewUser] = useState({
    name: '',
    email: '',
    password: ''
  });
  const [showPasswords, setShowPasswords] = useState<{[key: string]: boolean}>({});

  const { logout } = useCurrentUser();
  const { users, addUser, deleteUser } = useUsers();

  const resetDemoData = () => {
    if (window.confirm('Tem certeza que deseja resetar todos os dados demo? Isso irá limpar o localStorage e recarregar a página.')) {
      window.localStorage.clear();
      window.location.reload();
    }
  };

  // Inicializar usuários demo se não existirem
  useEffect(() => {
    if (users.length === 0) {
      addUser({
        name: 'Administrador',
        email: 'admin@fitai.com',
        password: 'admin123',
        isAdmin: true,
        emailVerified: true
      });
      addUser({
        name: 'João Silva',
        email: 'user@fitai.com',
        password: 'user123',
        isAdmin: false,
        emailVerified: true
      });
    }
  }, [users.length, addUser]);

  const handleAddUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (newUser.name && newUser.email && newUser.password) {
      addUser({
        ...newUser,
        isAdmin: false,
        emailVerified: true
      });
      setNewUser({ name: '', email: '', password: '' });
    }
  };

  const togglePasswordVisibility = (userId: string) => {
    setShowPasswords(prev => ({
      ...prev,
      [userId]: !prev[userId]
    }));
  };

  const regularUsers = users.filter(user => !user.isAdmin);

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 dark:from-blue-950 dark:to-indigo-950">
      {/* Header */}
      <div className="bg-white dark:bg-blue-900 shadow-sm border-b border-blue-100 dark:border-blue-800">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center py-4">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-blue-600 rounded-lg">
                <Settings className="w-6 h-6 text-white" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-blue-900 dark:text-blue-100">
                  Painel Administrativo
                </h1>
                <p className="text-blue-600 dark:text-blue-300">
                  Gerencie usuários do FitAI Coach
                </p>
              </div>
            </div>
            <div className="flex gap-2">
              <Button 
                onClick={resetDemoData}
                variant="outline"
                className="border-orange-200 text-orange-700 hover:bg-orange-50"
              >
                <Settings className="w-4 h-4 mr-2" />
                Reset Demo
              </Button>
              <Button 
                onClick={logout}
                variant="outline"
                className="border-blue-200 text-blue-700 hover:bg-blue-50"
              >
                <LogOut className="w-4 h-4 mr-2" />
                Sair
              </Button>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <Tabs defaultValue="users" className="space-y-6">
          <TabsList className="bg-white dark:bg-blue-900 border border-blue-200 dark:border-blue-700">
            <TabsTrigger value="users" className="data-[state=active]:bg-blue-600 data-[state=active]:text-white">
              <Users className="w-4 h-4 mr-2" />
              Usuários ({regularUsers.length})
            </TabsTrigger>
            <TabsTrigger value="add-user" className="data-[state=active]:bg-blue-600 data-[state=active]:text-white">
              <Plus className="w-4 h-4 mr-2" />
              Novo Usuário
            </TabsTrigger>
          </TabsList>

          {/* Lista de Usuários */}
          <TabsContent value="users" className="space-y-4">
            <Card className="border-blue-100 dark:border-blue-800">
              <CardHeader>
                <CardTitle className="text-blue-900 dark:text-blue-100">
                  Usuários Cadastrados
                </CardTitle>
              </CardHeader>
              <CardContent>
                {regularUsers.length === 0 ? (
                  <div className="text-center py-8 text-blue-600 dark:text-blue-400">
                    <Users className="w-12 h-12 mx-auto mb-4 opacity-50" />
                    <p>Nenhum usuário cadastrado ainda</p>
                  </div>
                ) : (
                  <div className="space-y-4">
                    {regularUsers.map((user) => (
                      <div key={user.id} className="flex items-center justify-between p-4 bg-blue-50 dark:bg-blue-900 rounded-lg border border-blue-100 dark:border-blue-800">
                        <div className="flex items-center gap-4">
                          <div className="p-2 bg-blue-600 rounded-full">
                            <User className="w-5 h-5 text-white" />
                          </div>
                          <div>
                            <h3 className="font-semibold text-blue-900 dark:text-blue-100">
                              {user.name}
                            </h3>
                            <p className="text-blue-600 dark:text-blue-300">
                              {user.email}
                            </p>
                            <div className="flex items-center gap-2 mt-1">
                              <span className="text-sm text-blue-700 dark:text-blue-300">
                                Senha: {showPasswords[user.id] ? user.password : '••••••••'}
                              </span>
                              <Button
                                size="sm"
                                variant="ghost"
                                onClick={() => togglePasswordVisibility(user.id)}
                                className="h-6 w-6 p-0 text-blue-600 hover:text-blue-800"
                              >
                                <Eye className="w-3 h-3" />
                              </Button>
                            </div>
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          <Badge 
                            variant={user.profile ? "default" : "secondary"}
                            className={user.profile ? "bg-green-100 text-green-800" : "bg-gray-100 text-gray-600"}
                          >
                            {user.profile ? 'Perfil Completo' : 'Perfil Pendente'}
                          </Badge>
                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => deleteUser(user.id)}
                            className="text-red-600 border-red-200 hover:bg-red-50"
                          >
                            <Trash2 className="w-4 h-4" />
                          </Button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          {/* Adicionar Usuário */}
          <TabsContent value="add-user">
            <Card className="border-blue-100 dark:border-blue-800">
              <CardHeader>
                <CardTitle className="text-blue-900 dark:text-blue-100">
                  Cadastrar Novo Usuário
                </CardTitle>
              </CardHeader>
              <CardContent>
                <form onSubmit={handleAddUser} className="space-y-4 max-w-md">
                  <div className="space-y-2">
                    <Label htmlFor="name" className="text-blue-800 dark:text-blue-200">
                      Nome Completo
                    </Label>
                    <Input
                      id="name"
                      value={newUser.name}
                      onChange={(e) => setNewUser(prev => ({ ...prev, name: e.target.value }))}
                      placeholder="Nome do usuário"
                      required
                      className="border-blue-200 dark:border-blue-700 focus:ring-blue-500"
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="email" className="text-blue-800 dark:text-blue-200">
                      Email
                    </Label>
                    <Input
                      id="email"
                      type="email"
                      value={newUser.email}
                      onChange={(e) => setNewUser(prev => ({ ...prev, email: e.target.value }))}
                      placeholder="email@exemplo.com"
                      required
                      className="border-blue-200 dark:border-blue-700 focus:ring-blue-500"
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="password" className="text-blue-800 dark:text-blue-200">
                      Senha
                    </Label>
                    <Input
                      id="password"
                      type="password"
                      value={newUser.password}
                      onChange={(e) => setNewUser(prev => ({ ...prev, password: e.target.value }))}
                      placeholder="Senha temporária"
                      required
                      className="border-blue-200 dark:border-blue-700 focus:ring-blue-500"
                    />
                  </div>

                  <Button 
                    type="submit" 
                    className="bg-blue-600 hover:bg-blue-700 text-white"
                  >
                    <Plus className="w-4 h-4 mr-2" />
                    Cadastrar Usuário
                  </Button>
                </form>

                <div className="mt-6 p-4 bg-blue-50 dark:bg-blue-900 rounded-lg">
                  <h4 className="font-semibold text-blue-900 dark:text-blue-100 mb-2">
                    Instruções:
                  </h4>
                  <ul className="text-sm text-blue-700 dark:text-blue-300 space-y-1">
                    <li>• O usuário receberá as credenciais de acesso</li>
                    <li>• No primeiro login, ele completará o perfil</li>
                    <li>• Após completar o perfil, terá acesso às funcionalidades</li>
                  </ul>
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

src/components/AppInitializer.tsx.content:
"use client";

import { useEffect, useState } from 'react';
import { useUsers } from '@/lib/hooks';

interface AppInitializerProps {
  children: React.ReactNode;
}

export function AppInitializer({ children }: AppInitializerProps) {
  const [isInitialized, setIsInitialized] = useState(false);
  const { users } = useUsers();

  useEffect(() => {
    // Aguardar um pouco para garantir que o localStorage foi carregado
    const timer = setTimeout(() => {
      setIsInitialized(true);
    }, 100);

    return () => clearTimeout(timer);
  }, []);

  if (!isInitialized) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 dark:from-blue-950 dark:to-indigo-950 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-blue-700 dark:text-blue-300">Carregando FitAI Coach...</p>
        </div>
      </div>
    );
  }

  return <>{children}</>;
}

src/components/PaymentScreen.tsx.content:
"use client";

import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { 
  CreditCard, 
  Lock, 
  ArrowLeft, 
  Check, 
  Crown, 
  Star, 
  Zap,
  Shield,
  Calendar,
  DollarSign
} from 'lucide-react';
import { PaymentData } from '@/lib/types';

interface PaymentScreenProps {
  selectedPlan: 'starter' | 'standard' | 'premium';
  onBack: () => void;
  onPaymentSuccess: () => void;
}

const planDetails = {
  starter: {
    name: 'Starter',
    price: 19.97,
    icon: <Zap className="w-6 h-6" />,
    color: 'from-green-500 to-emerald-600'
  },
  standard: {
    name: 'Standard',
    price: 29.97,
    icon: <Star className="w-6 h-6" />,
    color: 'from-blue-500 to-indigo-600'
  },
  premium: {
    name: 'Premium',
    price: 49.97,
    icon: <Crown className="w-6 h-6" />,
    color: 'from-purple-500 to-pink-600'
  }
};

export function PaymentScreen({ selectedPlan, onBack, onPaymentSuccess }: PaymentScreenProps) {
  const [paymentData, setPaymentData] = useState<PaymentData>({
    cardNumber: '',
    expiryDate: '',
    cvv: '',
    cardName: '',
    cpf: '',
    plan: selectedPlan
  });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [isProcessing, setIsProcessing] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  const plan = planDetails[selectedPlan];

  const formatCardNumber = (value: string) => {
    const numbers = value.replace(/\D/g, '');
    return numbers.replace(/(\d{4})(?=\d)/g, '$1 ').trim();
  };

  const formatExpiryDate = (value: string) => {
    const numbers = value.replace(/\D/g, '');
    if (numbers.length >= 2) {
      return numbers.substring(0, 2) + '/' + numbers.substring(2, 4);
    }
    return numbers;
  };

  const formatCPF = (value: string) => {
    const numbers = value.replace(/\D/g, '');
    return numbers.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.$2.$3-$4');
  };

  const validateForm = () => {
    const newErrors: Record<string, string> = {};

    if (!paymentData.cardNumber.replace(/\s/g, '')) {
      newErrors.cardNumber = 'Número do cartão é obrigatório';
    } else if (paymentData.cardNumber.replace(/\s/g, '').length !== 16) {
      newErrors.cardNumber = 'Número do cartão deve ter 16 dígitos';
    }

    if (!paymentData.expiryDate) {
      newErrors.expiryDate = 'Data de validade é obrigatória';
    } else if (!/^\d{2}\/\d{2}$/.test(paymentData.expiryDate)) {
      newErrors.expiryDate = 'Formato: MM/AA';
    }

    if (!paymentData.cvv) {
      newErrors.cvv = 'CVV é obrigatório';
    } else if (paymentData.cvv.length !== 3) {
      newErrors.cvv = 'CVV deve ter 3 dígitos';
    }

    if (!paymentData.cardName.trim()) {
      newErrors.cardName = 'Nome no cartão é obrigatório';
    }

    if (!paymentData.cpf) {
      newErrors.cpf = 'CPF é obrigatório';
    } else if (!/^\d{3}\.\d{3}\.\d{3}-\d{2}$/.test(paymentData.cpf)) {
      newErrors.cpf = 'Formato: 000.000.000-00';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleInputChange = (field: keyof PaymentData, value: string) => {
    let formattedValue = value;

    if (field === 'cardNumber') {
      formattedValue = formatCardNumber(value);
      if (formattedValue.replace(/\s/g, '').length > 16) return;
    } else if (field === 'expiryDate') {
      formattedValue = formatExpiryDate(value);
      if (formattedValue.replace(/\D/g, '').length > 4) return;
    } else if (field === 'cvv') {
      formattedValue = value.replace(/\D/g, '');
      if (formattedValue.length > 3) return;
    } else if (field === 'cpf') {
      formattedValue = formatCPF(value);
      if (formattedValue.replace(/\D/g, '').length > 11) return;
    }

    setPaymentData(prev => ({ ...prev, [field]: formattedValue }));

    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setIsProcessing(true);

    try {
      // Simular processamento do pagamento
      await new Promise(resolve => setTimeout(resolve, 3000));

      setShowSuccess(true);

      // Após 2 segundos, chamar onPaymentSuccess
      setTimeout(() => {
        onPaymentSuccess();
      }, 2000);
    } catch (error) {
      setErrors({ general: 'Erro ao processar pagamento. Tente novamente.' });
    } finally {
      setIsProcessing(false);
    }
  };

  if (showSuccess) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-green-50 to-emerald-100 dark:from-green-950 dark:to-emerald-950 flex items-center justify-center p-4">
        <Card className="w-full max-w-md shadow-xl border-green-100 dark:border-green-800">
          <CardHeader className="text-center">
            <div className="mx-auto w-16 h-16 bg-green-100 dark:bg-green-900 rounded-full flex items-center justify-center mb-4">
              <Check className="w-8 h-8 text-green-600" />
            </div>
            <CardTitle className="text-green-900 dark:text-green-100">
              Pagamento aprovado!
            </CardTitle>
          </CardHeader>
          <CardContent className="text-center space-y-4">
            <p className="text-green-700 dark:text-green-300">
              Seu plano <strong>{plan.name}</strong> foi ativado com sucesso!
            </p>
            <div className="bg-green-50 dark:bg-green-900 p-4 rounded-lg">
              <p className="text-sm text-green-600 dark:text-green-400">
                Você já pode aproveitar todos os recursos da IA.
              </p>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 dark:from-blue-950 dark:to-indigo-950 p-4">
      <div className="max-w-4xl mx-auto">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Plan Summary */}
          <div className="space-y-6">
            <Button
              variant="ghost"
              onClick={onBack}
              className="mb-4 text-blue-600 hover:text-blue-700"
            >
              <ArrowLeft className="w-4 h-4 mr-2" />
              Voltar aos planos
            </Button>

            <Card className="shadow-xl border-blue-100 dark:border-blue-800">
              <CardHeader>
                <CardTitle className="flex items-center gap-3 text-blue-900 dark:text-blue-100">
                  <div className={`p-3 bg-gradient-to-r ${plan.color} rounded-full text-white`}>
                    {plan.icon}
                  </div>
                  Resumo do pedido
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex items-center justify-between">
                  <span className="text-blue-800 dark:text-blue-200">Plano selecionado:</span>
                  <Badge className={`bg-gradient-to-r ${plan.color} text-white`}>
                    {plan.name}
                  </Badge>
                </div>

                <div className="flex items-center justify-between text-lg font-semibold">
                  <span className="text-blue-800 dark:text-blue-200">Valor mensal:</span>
                  <span className="text-blue-900 dark:text-blue-100">
                    R$ {plan.price.toFixed(2).replace('.', ',')}
                  </span>
                </div>

                <div className="border-t pt-4">
                  <div className="flex items-center justify-between text-xl font-bold">
                    <span className="text-blue-900 dark:text-blue-100">Total:</span>
                    <span className="text-blue-900 dark:text-blue-100">
                      R$ {plan.price.toFixed(2).replace('.', ',')}
                    </span>
                  </div>
                </div>

                <div className="bg-blue-50 dark:bg-blue-900 p-4 rounded-lg">
                  <div className="flex items-center gap-2 mb-2">
                    <Calendar className="w-4 h-4 text-blue-600" />
                    <span className="text-sm font-semibold text-blue-800 dark:text-blue-200">
                      Cobrança recorrente
                    </span>
                  </div>
                  <p className="text-xs text-blue-600 dark:text-blue-400">
                    Renovação automática todo mês. Cancele quando quiser.
                  </p>
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Payment Form */}
          <Card className="shadow-xl border-blue-100 dark:border-blue-800">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-blue-900 dark:text-blue-100">
                <CreditCard className="w-5 h-5" />
                Dados do pagamento
              </CardTitle>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="cardNumber" className="text-blue-800 dark:text-blue-200">
                    Número do cartão
                  </Label>
                  <Input
                    id="cardNumber"
                    type="text"
                    value={paymentData.cardNumber}
                    onChange={(e) => handleInputChange('cardNumber', e.target.value)}
                    placeholder="0000 0000 0000 0000"
                    className={`border-blue-200 dark:border-blue-700 focus:ring-blue-500 ${
                      errors.cardNumber ? 'border-red-500' : ''
                    }`}
                  />
                  {errors.cardNumber && (
                    <p className="text-red-500 text-sm">{errors.cardNumber}</p>
                  )}
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="expiryDate" className="text-blue-800 dark:text-blue-200">
                      Validade
                    </Label>
                    <Input
                      id="expiryDate"
                      type="text"
                      value={paymentData.expiryDate}
                      onChange={(e) => handleInputChange('expiryDate', e.target.value)}
                      placeholder="MM/AA"
                      className={`border-blue-200 dark:border-blue-700 focus:ring-blue-500 ${
                        errors.expiryDate ? 'border-red-500' : ''
                      }`}
                    />
                    {errors.expiryDate && (
                      <p className="text-red-500 text-sm">{errors.expiryDate}</p>
                    )}
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="cvv" className="text-blue-800 dark:text-blue-200">
                      CVV
                    </Label>
                    <Input
                      id="cvv"
                      type="text"
                      value={paymentData.cvv}
                      onChange={(e) => handleInputChange('cvv', e.target.value)}
                      placeholder="000"
                      className={`border-blue-200 dark:border-blue-700 focus:ring-blue-500 ${
                        errors.cvv ? 'border-red-500' : ''
                      }`}
                    />
                    {errors.cvv && (
                      <p className="text-red-500 text-sm">{errors.cvv}</p>
                    )}
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="cardName" className="text-blue-800 dark:text-blue-200">
                    Nome no cartão
                  </Label>
                  <Input
                    id="cardName"
                    type="text"
                    value={paymentData.cardName}
                    onChange={(e) => handleInputChange('cardName', e.target.value)}
                    placeholder="Nome como está no cartão"
                    className={`border-blue-200 dark:border-blue-700 focus:ring-blue-500 ${
                      errors.cardName ? 'border-red-500' : ''
                    }`}
                  />
                  {errors.cardName && (
                    <p className="text-red-500 text-sm">{errors.cardName}</p>
                  )}
                </div>

                <div className="space-y-2">
                  <Label htmlFor="cpf" className="text-blue-800 dark:text-blue-200">
                    CPF do titular
                  </Label>
                  <Input
                    id="cpf"
                    type="text"
                    value={paymentData.cpf}
                    onChange={(e) => handleInputChange('cpf', e.target.value)}
                    placeholder="000.000.000-00"
                    className={`border-blue-200 dark:border-blue-700 focus:ring-blue-500 ${
                      errors.cpf ? 'border-red-500' : ''
                    }`}
                  />
                  {errors.cpf && (
                    <p className="text-red-500 text-sm">{errors.cpf}</p>
                  )}
                </div>

                {errors.general && (
                  <div className="text-red-600 text-sm text-center bg-red-50 dark:bg-red-950 p-2 rounded">
                    {errors.general}
                  </div>
                )}

                <div className="bg-green-50 dark:bg-green-900 p-4 rounded-lg">
                  <div className="flex items-center gap-2 mb-2">
                    <Shield className="w-4 h-4 text-green-600" />
                    <span className="text-sm font-semibold text-green-800 dark:text-green-200">
                      Pagamento seguro
                    </span>
                  </div>
                  <p className="text-xs text-green-600 dark:text-green-400">
                    Seus dados são protegidos com criptografia SSL de 256 bits.
                  </p>
                </div>

                <Button 
                  type="submit" 
                  className={`w-full bg-gradient-to-r ${plan.color} hover:opacity-90 text-white text-lg py-6`}
                  disabled={isProcessing}
                >
                  {isProcessing ? (
                    <>
                      <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                      Processando pagamento...
                    </>
                  ) : (
                    <>
                      <Lock className="w-4 h-4 mr-2" />
                      Finalizar pagamento - R$ {plan.price.toFixed(2).replace('.', ',')}
                    </>
                  )}
                </Button>
              </form>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

src/components/SubscriptionPlans.tsx.content:
"use client";

import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Check, Crown, Star, Zap, ArrowRight } from 'lucide-react';
import { SubscriptionPlan } from '@/lib/types';
import { IuguCheckout } from './IuguCheckout';
import { useCurrentUser, useUsers } from '@/lib/hooks';
import { toast } from '@/hooks/use-toast';

interface SubscriptionPlansProps {
  onSelectPlan: (planId: 'starter' | 'standard' | 'premium') => void;
  onClose: () => void;
  isNewUserFlow?: boolean;
}

const plans: SubscriptionPlan[] = [
  {
    id: 'starter',
    name: 'Starter',
    price: 19.97,
    features: {
      dietsPerMonth: 1,
      workoutsPerMonth: 1,
      canChangeDiet: false,
      supplementConsultation: false
    },
    description: [
      '1 dieta nova por mês',
      '1 treino por mês',
      'Análise corporal básica',
      'Suporte por email'
    ]
  },
  {
    id: 'standard',
    name: 'Standard',
    price: 29.97,
    features: {
      dietsPerMonth: 2,
      workoutsPerMonth: 2,
      canChangeDiet: true,
      supplementConsultation: false
    },
    description: [
      'Pode mudar dieta no meio do mês',
      '2 treinos por mês',
      'Análise corporal avançada',
      'Suporte prioritário',
      'Relatórios de progresso'
    ]
  },
  {
    id: 'premium',
    name: 'Premium',
    price: 49.97,
    features: {
      dietsPerMonth: 'unlimited',
      workoutsPerMonth: 4,
      canChangeDiet: true,
      supplementConsultation: true,
      minimumMonths: 4
    },
    description: [
      'Dietas ilimitadas (quando quiser)',
      '4 treinos por mês',
      'Consultoria de suplementação',
      'Dúvidas sobre manipulados',
      'Suporte 24/7',
      'Análise corporal premium',
      'Acompanhamento personalizado'
    ]
  }
];

export function SubscriptionPlans({ onSelectPlan, onClose, isNewUserFlow = false }: SubscriptionPlansProps) {
  const [selectedPlan, setSelectedPlan] = useState<'starter' | 'standard' | 'premium' | null>(null);
  const [showCheckout, setShowCheckout] = useState(false);
  const [checkoutPlan, setCheckoutPlan] = useState<{
    id: 'starter' | 'standard' | 'premium';
    identifier: string;
    name: string;
    price: number;
  } | null>(null);

  const { currentUser } = useCurrentUser();
  const { updateUser } = useUsers();

  const getPlanIcon = (planId: string) => {
    switch (planId) {
      case 'starter':
        return <Zap className="w-6 h-6" />;
      case 'standard':
        return <Star className="w-6 h-6" />;
      case 'premium':
        return <Crown className="w-6 h-6" />;
      default:
        return <Zap className="w-6 h-6" />;
    }
  };

  const getPlanColor = (planId: string) => {
    switch (planId) {
      case 'starter':
        return 'from-green-500 to-emerald-600';
      case 'standard':
        return 'from-blue-500 to-indigo-600';
      case 'premium':
        return 'from-purple-500 to-pink-600';
      default:
        return 'from-green-500 to-emerald-600';
    }
  };

  // Mapear planos para identificadores da Iugu
  const getIuguPlanData = (planId: 'starter' | 'standard' | 'premium') => {
    const iuguMapping: {
      [K in 'starter' | 'standard' | 'premium']: {
        id: K;
        identifier: string;
        name: string;
        price: number;
      };
    } = {
      starter: {
        id: 'starter' as const,
        identifier: 'fitai_starter_monthly',
        name: 'FitAI Starter',
        price: 1997 // R$ 19,97 em centavos
      },
      standard: {
        id: 'standard' as const,
        identifier: 'fitai_standard_monthly',
        name: 'FitAI Standard',
        price: 2997 // R$ 29,97 em centavos
      },
      premium: {
        id: 'premium' as const,
        identifier: 'fitai_premium_monthly',
        name: 'FitAI Premium',
        price: 4997 // R$ 49,97 em centavos
      }
    };
    return iuguMapping[planId];
  };

  const handleSelectPlan = (planId: 'starter' | 'standard' | 'premium') => {
    setSelectedPlan(planId);

    // Preparar dados do checkout
    const iuguPlan = getIuguPlanData(planId);
    setCheckoutPlan(iuguPlan);

    setTimeout(() => {
      setShowCheckout(true);
    }, 300);
  };

  const handleCheckoutSuccess = (subscriptionData: any) => {
    console.log('[SUBSCRIPTION] Pagamento realizado com sucesso:', subscriptionData);

    // Verificar se currentUser existe antes de usar
    if (currentUser && currentUser.id) {
      // Atualizar usuário com dados da assinatura
      const updatedUser = {
        ...currentUser,
        subscription: {
          plan: checkoutPlan?.id as 'starter' | 'standard' | 'premium',
          status: 'active' as const,
          startDate: new Date(),
          endDate: new Date(new Date().setMonth(new Date().getMonth() + 1)),
          canDowngrade: checkoutPlan?.id !== 'premium',
          downgradableDate: checkoutPlan?.id !== 'starter' ? new Date(new Date().setMonth(new Date().getMonth() + 4)) : undefined,
          dietsUsedThisMonth: 0,
          workoutsUsedThisMonth: 0,
          bodyAnalysesUsedThisMonth: 0,
          monthlyResetDate: new Date(new Date().getFullYear(), new Date().getMonth() + 1, 1),
          // Dados da integração Iugu
          iugu: {
            customerId: subscriptionData.customer_id,
            subscriptionId: subscriptionData.id,
            paymentMethodId: subscriptionData.payment_method?.id,
            lastInvoiceStatus: 'active',
            nextChargeDate: new Date(new Date().setMonth(new Date().getMonth() + 1))
          }
        }
      };

      updateUser(currentUser.id, updatedUser);

      toast({
        title: "🎉 Assinatura ativada!",
        description: `Bem-vindo ao plano ${checkoutPlan?.name}! Agora você tem acesso completo ao FitAI.`,
      });

      // Chamar callback original
      onSelectPlan(checkoutPlan?.id as 'starter' | 'standard' | 'premium');
    } else {
      // Para novos usuários ou quando currentUser é null, apenas chamar callback
      console.log('[SUBSCRIPTION] New user flow - skipping user update');

      toast({
        title: "🎉 Assinatura ativada!",
        description: `Bem-vindo ao plano ${checkoutPlan?.name}! Agora você tem acesso completo ao FitAI.`,
      });

      // Chamar callback original mesmo sem currentUser
      onSelectPlan(checkoutPlan?.id as 'starter' | 'standard' | 'premium');
    }
  };

  const handleCheckoutError = (error: string) => {
    console.error('[SUBSCRIPTION] Erro no checkout:', error);

    toast({
      variant: "destructive",
      title: "❌ Erro no pagamento",
      description: error || "Ocorreu um erro ao processar seu pagamento. Tente novamente.",
    });

    // Voltar para seleção de planos
    setShowCheckout(false);
    setSelectedPlan(null);
    setCheckoutPlan(null);
  };

  const handleBackFromCheckout = () => {
    setShowCheckout(false);
    setSelectedPlan(null);
    setCheckoutPlan(null);
  };

  // Se estivermos no checkout, mostrar o componente de checkout
  // Durante fluxo de novo usuário, currentUser pode ser null inicialmente, mas deve permitir checkout
  if (showCheckout && checkoutPlan && (currentUser || isNewUserFlow)) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-green-50 to-emerald-100 dark:from-green-950 dark:to-emerald-950 p-4 flex items-center justify-center">
        <IuguCheckout
          planIdentifier={checkoutPlan.identifier as 'fitai_starter_monthly' | 'fitai_standard_monthly' | 'fitai_premium_monthly'}
          planName={checkoutPlan.name}
          planPrice={checkoutPlan.price}
          onSuccess={handleCheckoutSuccess}
          onError={handleCheckoutError}
          onBack={handleBackFromCheckout}
          userId={currentUser?.id || `temp-user-${Date.now()}`}
          userEmail={currentUser?.email || 'temp@example.com'}
          userName={currentUser?.name || 'Usuário Temporário'}
          userCPF={currentUser?.cpf}
          userPhone={currentUser?.phone}
        />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 dark:from-blue-950 dark:to-indigo-950 p-4">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold text-blue-900 dark:text-blue-100 mb-4">
            Você ainda não assinou um plano!
          </h1>
          <p className="text-lg text-blue-700 dark:text-blue-300 mb-2">
            Para continuar e ter acesso às informações da IA,
          </p>
          <p className="text-lg text-blue-700 dark:text-blue-300">
            escolha o plano que melhor se adequa a você.
          </p>
        </div>

        {/* Plans Grid */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
          {plans.map((plan) => (
            <Card
              key={plan.id}
              className={`relative overflow-hidden transition-all duration-300 hover:scale-105 cursor-pointer ${
                selectedPlan === plan.id
                  ? 'ring-4 ring-blue-500 shadow-2xl'
                  : 'shadow-xl hover:shadow-2xl'
              } ${
                plan.id === 'premium'
                  ? 'border-2 border-purple-200 dark:border-purple-800'
                  : 'border-blue-100 dark:border-blue-800'
              }`}
              onClick={() => handleSelectPlan(plan.id)}
            >
              {plan.id === 'premium' && (
                <div className="absolute top-0 right-0 bg-gradient-to-r from-purple-500 to-pink-500 text-white px-3 py-1 text-sm font-semibold">
                  MAIS POPULAR
                </div>
              )}

              <CardHeader className="text-center pb-4">
                <div className={`mx-auto w-16 h-16 bg-gradient-to-r ${getPlanColor(plan.id)} rounded-full flex items-center justify-center mb-4 text-white`}>
                  {getPlanIcon(plan.id)}
                </div>
                <CardTitle className="text-2xl font-bold text-blue-900 dark:text-blue-100">
                  {plan.name}
                </CardTitle>
                <div className="text-center">
                  <span className="text-3xl font-bold text-blue-900 dark:text-blue-100">
                    R$ {plan.price.toFixed(2).replace('.', ',')}
                  </span>
                  <span className="text-blue-600 dark:text-blue-400">/mês</span>
                </div>
                {plan.features.minimumMonths && (
                  <Badge variant="outline" className="mx-auto mt-2 border-purple-300 text-purple-700">
                    Mínimo {plan.features.minimumMonths} meses
                  </Badge>
                )}
              </CardHeader>

              <CardContent className="pt-0">
                <ul className="space-y-3">
                  {plan.description.map((feature, index) => (
                    <li key={index} className="flex items-start gap-3">
                      <Check className="w-5 h-5 text-green-500 mt-0.5 flex-shrink-0" />
                      <span className="text-blue-800 dark:text-blue-200 text-sm">
                        {feature}
                      </span>
                    </li>
                  ))}
                </ul>

                <Button
                  className={`w-full mt-6 bg-gradient-to-r ${getPlanColor(plan.id)} hover:opacity-90 text-white transition-all duration-300 ${
                    selectedPlan === plan.id ? 'scale-105' : ''
                  }`}
                  onClick={(e) => {
                    e.stopPropagation();
                    handleSelectPlan(plan.id);
                  }}
                >
                  {selectedPlan === plan.id ? (
                    <>
                      Selecionado
                      <ArrowRight className="w-4 h-4 ml-2" />
                    </>
                  ) : (
                    'Escolher plano'
                  )}
                </Button>
              </CardContent>
            </Card>
          ))}
        </div>

        {/* Important Notes */}
        <div className="bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800 rounded-lg p-6 mb-6">
          <h3 className="font-semibold text-yellow-800 dark:text-yellow-200 mb-3">
            📋 Informações importantes sobre os planos:
          </h3>
          <ul className="space-y-2 text-sm text-yellow-700 dark:text-yellow-300">
            <li>• <strong>Upgrade:</strong> Pode ser feito a qualquer momento</li>
            <li>• <strong>Downgrade:</strong> Só é possível após 4 meses na categoria atual</li>
            <li>• <strong>Premium:</strong> Permanência mínima de 4 meses</li>
            <li>• <strong>Renovação:</strong> Automática mensalmente</li>
            <li>• <strong>Cancelamento:</strong> Pode ser feito a qualquer momento</li>
          </ul>
        </div>

        {/* Back Button - só mostrar se NÃO for fluxo de novo usuário */}
        {!isNewUserFlow && (
          <div className="text-center">
            <Button
              variant="ghost"
              onClick={onClose}
              className="text-blue-600 hover:text-blue-700"
            >
              Voltar para o app
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}

