          {/* AI Coach Tab - Premium Feature */}
          <TabsContent value="ai-chat">
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2">
                  <Heart className="w-5 h-5 text-red-500" />
                  IA Coach - Tire suas dúvidas
                </CardTitle>
