    document.querySelectorAll('.lasy-highlight').forEach(el => {
      el.classList.remove('lasy-highlight');
      el.removeAttribute('data-lasy-selector');
    });

    // Remover estilos
    if (selectorStyle) {
      selectorStyle.remove();
      selectorStyle = null;
    }

    console.log('[Lasy Element Selector] Deactivated');
  }

