src/components/AdminActivityLogs.tsx.content:
"use client";

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { useActivityLogger, useUsers } from '@/lib/hooks';
import { ActivityLog } from '@/lib/types';
import { 
  FileText, 
  Search, 
  Filter, 
  Calendar,
  User,
  Activity,
  CheckCircle,
  XCircle,
  AlertTriangle,
  Clock,
  Eye,
  Download,
  RefreshCw,
  TrendingUp,
  BarChart3,
  LogIn,
  LogOut,
  Utensils,
  Dumbbell,
  Camera,
  MessageCircle,
  Shield,
  Settings,
  Plus,
  Copy,
  ChevronLeft,
  ChevronRight,
  X
} from 'lucide-react';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';

interface AdminActivityLogsProps {
  selectedUserId?: string;
  selectedUserName?: string;
  onClearUserFilter?: () => void;
}

export function AdminActivityLogs({ selectedUserId, selectedUserName, onClearUserFilter }: AdminActivityLogsProps) {
  const { getActivityLogs, getLogStats } = useActivityLogger();
  const { users } = useUsers();

  // Estados para filtros
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedUser, setSelectedUser] = useState<string>(selectedUserId || 'all');
  const [selectedAction, setSelectedAction] = useState<string>('all');
  const [selectedStatus, setSelectedStatus] = useState<string>('all');
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');

  // Estados para paginação
  const [currentPage, setCurrentPage] = useState(1);
  const [logsPerPage] = useState(50);

  // Estados para dados
  const [logs, setLogs] = useState<ActivityLog[]>([]);
  const [totalLogs, setTotalLogs] = useState(0);
  const [hasMore, setHasMore] = useState(false);
  const [stats, setStats] = useState<any>(null);
  const [isLoading, setIsLoading] = useState(false);

  // Estados para visualização
  const [selectedLog, setSelectedLog] = useState<ActivityLog | null>(null);
  const [showLogDetails, setShowLogDetails] = useState(false);
  const [showStats, setShowStats] = useState(false);

  // Carregar logs e estatísticas
  const loadLogs = () => {
    setIsLoading(true);

    try {
      const filters = {
        search: searchTerm.trim() || undefined,
        userId: selectedUser !== 'all' ? selectedUser : undefined,
        action: selectedAction !== 'all' ? selectedAction : undefined,
        status: selectedStatus !== 'all' ? (selectedStatus as any) : undefined,
        startDate: startDate ? new Date(startDate) : undefined,
        endDate: endDate ? new Date(endDate) : undefined,
        limit: logsPerPage,
        offset: (currentPage - 1) * logsPerPage
      };

      const result = getActivityLogs(filters);
      setLogs(result.logs);
      setTotalLogs(result.total);
      setHasMore(result.hasMore);

      // Carregar estatísticas
      const logStats = getLogStats();
      setStats(logStats);
    } catch (error) {
      console.error('Erro ao carregar logs:', error);
    } finally {
      setIsLoading(false);
    }
  };

  // Definir usuário selecionado quando prop mudou
  useEffect(() => {
    if (selectedUserId) {
      setSelectedUser(selectedUserId);
      setCurrentPage(1);
    }
  }, [selectedUserId]);

  // Recarregar logs quando filtros mudarem
  useEffect(() => {
    setCurrentPage(1); // Reset página quando filtros mudarem
  }, [searchTerm, selectedUser, selectedAction, selectedStatus, startDate, endDate]);

  useEffect(() => {
    loadLogs();
  }, [currentPage, searchTerm, selectedUser, selectedAction, selectedStatus, startDate, endDate]);

  // Função para obter ícone da ação
  const getActionIcon = (action: string) => {
    switch (action) {
      case 'LOGIN': return <LogIn className="w-4 h-4 text-green-600" />;
      case 'LOGOUT': return <LogOut className="w-4 h-4 text-gray-600" />;
      case 'LOGIN_FAILED': return <XCircle className="w-4 h-4 text-red-600" />;
      case 'GENERATE_DIET': return <Utensils className="w-4 h-4 text-blue-600" />;
      case 'EDIT_DIET_CHAT': return <MessageCircle className="w-4 h-4 text-purple-600" />;
      case 'GENERATE_WORKOUT': return <Dumbbell className="w-4 h-4 text-orange-600" />;
      case 'BODY_ANALYSIS': return <Camera className="w-4 h-4 text-pink-600" />;
      case 'AI_CHAT': return <MessageCircle className="w-4 h-4 text-indigo-600" />;
      case 'PROFILE_UPDATE': return <User className="w-4 h-4 text-teal-600" />;
      case 'SUBSCRIPTION_CHANGE': return <Shield className="w-4 h-4 text-yellow-600" />;
      default: return <Activity className="w-4 h-4 text-gray-600" />;
    }
  };

  // Função para obter cor do status
  const getStatusColor = (status: string) => {
    switch (status) {
      case 'success': return 'bg-green-100 text-green-800';
      case 'error': return 'bg-red-100 text-red-800';
      case 'warning': return 'bg-yellow-100 text-yellow-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  // Função para copiar logs para clipboard
  const copyLogsToClipboard = () => {
    const logText = logs.map(log => {
      return `${format(new Date(log.timestamp), 'dd/MM/yyyy HH:mm:ss', { locale: ptBR })} | ${log.userName} (${log.userEmail}) | ${log.action} | ${log.status.toUpperCase()} | ${log.details}`;
    }).join('\n');

    navigator.clipboard.writeText(logText).then(() => {
      alert('Logs copiados para a área de transferência!');
    }).catch((error) => {
      console.error('Erro ao copiar logs:', error);
      alert('Erro ao copiar logs. Tente novamente.');
    });
  };

  // Obter usuários únicos dos logs para filtro
  const getUsersFromLogs = () => {
    const uniqueUsers = new Set();
    logs.forEach(log => {
      uniqueUsers.add(`${log.userId}:${log.userName}:${log.userEmail}`);
    });
    return Array.from(uniqueUsers).map(item => {
      const [userId, userName, userEmail] = (item as string).split(':');
      return { userId, userName, userEmail };
    });
  };

  // Obter ações únicas dos logs para filtro
  const getActionsFromLogs = () => {
    const actions = [...new Set(logs.map(log => log.action))];
    return actions.sort();
  };

  const totalPages = Math.ceil(totalLogs / logsPerPage);

  return (
    <div className="space-y-6">
      {/* Header com estatísticas */}
      <div>
        <h2 className="text-2xl font-bold text-gray-900 mb-4 flex items-center">
          <FileText className="w-6 h-6 mr-2" />
          Logs de Atividade
        </h2>

        {/* Filtro de usuário específico */}
        {selectedUserId && selectedUserName && (
          <div className="mb-4 p-3 bg-blue-50 border border-blue-200 rounded-lg">
            <div className="flex items-center justify-between">
              <div className="flex items-center">
                <User className="w-5 h-5 text-blue-600 mr-2" />
                <span className="font-medium text-blue-900">
                  Visualizando logs de: <strong>{selectedUserName}</strong>
                </span>
              </div>
              {onClearUserFilter && (
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={onClearUserFilter}
                  className="text-blue-600 hover:text-blue-800"
                >
                  <X className="w-4 h-4 mr-1" />
                  Limpar filtro
                </Button>
              )}
            </div>
          </div>
        )}

        {/* Estatísticas rápidas */}
        {stats && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
            <Card>
              <CardContent className="p-4">
                <div className="flex items-center">
                  <Activity className="w-8 h-8 text-blue-600" />
                  <div className="ml-3">
                    <p className="text-sm font-medium text-gray-500">Total</p>
                    <p className="text-2xl font-bold text-gray-900">{stats.total}</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardContent className="p-4">
                <div className="flex items-center">
                  <Calendar className="w-8 h-8 text-green-600" />
                  <div className="ml-3">
                    <p className="text-sm font-medium text-gray-500">Hoje</p>
                    <p className="text-2xl font-bold text-gray-900">{stats.today}</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardContent className="p-4">
                <div className="flex items-center">
                  <CheckCircle className="w-8 h-8 text-green-600" />
                  <div className="ml-3">
                    <p className="text-sm font-medium text-gray-500">Sucesso</p>
                    <p className="text-2xl font-bold text-gray-900">{stats.byStatus.success}</p>
                  </div>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardContent className="p-4">
                <div className="flex items-center">
                  <XCircle className="w-8 h-8 text-red-600" />
                  <div className="ml-3">
                    <p className="text-sm font-medium text-gray-500">Erros</p>
                    <p className="text-2xl font-bold text-gray-900">{stats.byStatus.error}</p>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        )}

        {/* Botões de ação */}
        <div className="flex space-x-2 mb-4">
          <Button onClick={loadLogs} variant="outline" size="sm">
            <RefreshCw className="w-4 h-4 mr-1" />
            Atualizar
          </Button>

          {logs.length > 0 && (
            <Button onClick={copyLogsToClipboard} variant="outline" size="sm">
              <Copy className="w-4 h-4 mr-1" />
              Copiar
            </Button>
          )}

          {stats && (
            <Button onClick={() => setShowStats(true)} variant="outline" size="sm">
              <BarChart3 className="w-4 h-4 mr-1" />
              Estatísticas
            </Button>
          )}
        </div>
      </div>

      {/* Filtros */}
      <Card>
        <CardContent className="p-4">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4">
            {/* Busca */}
            <div className="lg:col-span-2">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                <Input
                  placeholder="Buscar logs..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10"
                />
              </div>
            </div>

            {/* Filtro por usuário */}
            <div>
              <Select value={selectedUser} onValueChange={setSelectedUser}>
                <SelectTrigger>
                  <SelectValue placeholder="Usuário" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos usuários</SelectItem>
                  {users.map(user => (
                    <SelectItem key={user.id} value={user.id}>
                      {user.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Filtro por ação */}
            <div>
              <Select value={selectedAction} onValueChange={setSelectedAction}>
                <SelectTrigger>
                  <SelectValue placeholder="Ação" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todas ações</SelectItem>
                  <SelectItem value="LOGIN">Login</SelectItem>
                  <SelectItem value="LOGOUT">Logout</SelectItem>
                  <SelectItem value="GENERATE_DIET">Dieta</SelectItem>
                  <SelectItem value="GENERATE_WORKOUT">Treino</SelectItem>
                  <SelectItem value="BODY_ANALYSIS">Análise</SelectItem>
                  <SelectItem value="AI_CHAT">IA Chat</SelectItem>
                  <SelectItem value="PROFILE_UPDATE">Perfil</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Filtro por status */}
            <div>
              <Select value={selectedStatus} onValueChange={setSelectedStatus}>
                <SelectTrigger>
                  <SelectValue placeholder="Status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos status</SelectItem>
                  <SelectItem value="success">Sucesso</SelectItem>
                  <SelectItem value="error">Erro</SelectItem>
                  <SelectItem value="warning">Aviso</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Filtros de data */}
            <div className="md:col-span-2 lg:col-span-1 xl:col-span-1">
              <Input
                type="date"
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="w-full"
              />
            </div>
          </div>

          {/* Filtros ativos */}
          {(searchTerm || selectedUser !== 'all' || selectedAction !== 'all' || selectedStatus !== 'all' || startDate) && (
            <div className="flex items-center space-x-2 mt-3 pt-3 border-t">
              <span className="text-sm text-gray-600">Filtros ativos:</span>
              {searchTerm && (
                <Badge variant="outline">
                  Busca: {searchTerm}
                  <Button
                    variant="ghost"
                    size="sm"
                    className="ml-1 h-4 w-4 p-0"
                    onClick={() => setSearchTerm('')}
                  >
                    ×
                  </Button>
                </Badge>
              )}
              {selectedUser !== 'all' && (
                <Badge variant="outline">
                  Usuário: {users.find(u => u.id === selectedUser)?.name}
                  <Button
                    variant="ghost"
                    size="sm"
                    className="ml-1 h-4 w-4 p-0"
                    onClick={() => setSelectedUser('all')}
                  >
                    ×
                  </Button>
                </Badge>
              )}
              {selectedAction !== 'all' && (
                <Badge variant="outline">
                  Ação: {selectedAction}
                  <Button
                    variant="ghost"
                    size="sm"
                    className="ml-1 h-4 w-4 p-0"
                    onClick={() => setSelectedAction('all')}
                  >
                    ×
                  </Button>
                </Badge>
              )}
              {selectedStatus !== 'all' && (
                <Badge variant="outline">
                  Status: {selectedStatus}
                  <Button
                    variant="ghost"
                    size="sm"
                    className="ml-1 h-4 w-4 p-0"
                    onClick={() => setSelectedStatus('all')}
                  >
                    ×
                  </Button>
                </Badge>
              )}
              <Button
                variant="ghost"
                size="sm"
                onClick={() => {
                  setSearchTerm('');
                  setSelectedUser('all');
                  setSelectedAction('all');
                  setSelectedStatus('all');
                  setStartDate('');
                  setEndDate('');
                }}
              >
                Limpar todos
              </Button>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Lista de logs */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center justify-between">
            <span>
              Logs de Atividade ({totalLogs} registros)
            </span>
            {isLoading && (
              <RefreshCw className="w-4 h-4 animate-spin" />
            )}
          </CardTitle>
        </CardHeader>

        <CardContent className="p-0">
          {logs.length > 0 ? (
            <div className="divide-y">
              {logs.map((log) => (
                <div
                  key={log.id}
                  className="p-4 hover:bg-gray-50 cursor-pointer transition-colors"
                  onClick={() => {
                    setSelectedLog(log);
                    setShowLogDetails(true);
                  }}
                >
                  <div className="flex items-start space-x-3">
                    <div className="flex-shrink-0 mt-1">
                      {getActionIcon(log.action)}
                    </div>

                    <div className="flex-1 min-w-0">
                      <div className="flex items-center space-x-2 mb-1">
                        <span className="font-medium text-gray-900">
                          {log.userName}
                        </span>
                        <span className="text-sm text-gray-500">
                          ({log.userEmail})
                        </span>
                        <Badge className={getStatusColor(log.status)}>
                          {log.status}
                        </Badge>
                      </div>

                      <p className="text-sm text-gray-600 mb-2">
                        {log.details}
                      </p>

                      <div className="flex items-center space-x-4 text-xs text-gray-500">
                        <span className="flex items-center">
                          <Clock className="w-3 h-3 mr-1" />
                          {format(new Date(log.timestamp), 'dd/MM/yyyy HH:mm:ss', { locale: ptBR })}
                        </span>
                        <span className="flex items-center">
                          <Activity className="w-3 h-3 mr-1" />
                          {log.action}
                        </span>
                        {log.ip && (
                          <span className="flex items-center">
                            IP: {log.ip}
                          </span>
                        )}
                      </div>
                    </div>

                    <div className="flex-shrink-0">
                      <Button variant="ghost" size="sm">
                        <Eye className="w-4 h-4" />
                      </Button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="p-8 text-center">
              <FileText className="w-12 h-12 text-gray-400 mx-auto mb-4" />
              <h3 className="text-lg font-medium text-gray-900 mb-2">
                {isLoading ? 'Carregando logs...' : 'Nenhum log encontrado'}
              </h3>
              {!isLoading && (
                <p className="text-gray-500">
                  Tente ajustar os filtros ou aguarde por mais atividades.
                </p>
              )}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Paginação */}
      {totalPages > 1 && (
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <p className="text-sm text-gray-600">
                Página {currentPage} de {totalPages} ({totalLogs} logs)
              </p>

              <div className="flex space-x-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setCurrentPage(Math.max(1, currentPage - 1))}
                  disabled={currentPage === 1}
                >
                  <ChevronLeft className="w-4 h-4 mr-1" />
                  Anterior
                </Button>

                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setCurrentPage(Math.min(totalPages, currentPage + 1))}
                  disabled={currentPage === totalPages}
                >
                  Próximo
                  <ChevronRight className="w-4 h-4 ml-1" />
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Dialog para detalhes do log */}
      <Dialog open={showLogDetails} onOpenChange={setShowLogDetails}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center">
              {selectedLog && getActionIcon(selectedLog.action)}
              <span className="ml-2">Detalhes do Log</span>
            </DialogTitle>
          </DialogHeader>

          {selectedLog && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label className="text-sm font-medium text-gray-500">Usuário</Label>
                  <p className="font-medium">{selectedLog.userName}</p>
                  <p className="text-sm text-gray-600">{selectedLog.userEmail}</p>
                </div>
                <div>
                  <Label className="text-sm font-medium text-gray-500">Data/Hora</Label>
                  <p className="font-medium">
                    {format(new Date(selectedLog.timestamp), 'dd/MM/yyyy HH:mm:ss', { locale: ptBR })}
                  </p>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label className="text-sm font-medium text-gray-500">Ação</Label>
                  <p className="font-medium">{selectedLog.action}</p>
                </div>
                <div>
                  <Label className="text-sm font-medium text-gray-500">Status</Label>
                  <Badge className={getStatusColor(selectedLog.status)}>
                    {selectedLog.status}
                  </Badge>
                </div>
              </div>

              <div>
                <Label className="text-sm font-medium text-gray-500">Detalhes</Label>
                <p className="mt-1 p-3 bg-gray-50 rounded-lg text-sm">
                  {selectedLog.details}
                </p>
              </div>

              {selectedLog.metadata && (
                <div>
                  <Label className="text-sm font-medium text-gray-500">Dados Extras</Label>
                  <pre className="mt-1 p-3 bg-gray-50 rounded-lg text-xs overflow-auto">
                    {JSON.stringify(selectedLog.metadata, null, 2)}
                  </pre>
                </div>
              )}

              {selectedLog.ip && (
                <div>
                  <Label className="text-sm font-medium text-gray-500">Endereço IP</Label>
                  <p className="font-mono text-sm">{selectedLog.ip}</p>
                </div>
              )}
            </div>
          )}
        </DialogContent>
      </Dialog>

      {/* Dialog para estatísticas detalhadas */}
      <Dialog open={showStats} onOpenChange={setShowStats}>
        <DialogContent className="max-w-4xl">
          <DialogHeader>
            <DialogTitle className="flex items-center">
              <BarChart3 className="w-5 h-5 mr-2" />
              Estatísticas Detalhadas
            </DialogTitle>
          </DialogHeader>

          {stats && (
            <div className="space-y-6">
              {/* Estatísticas por período */}
              <div>
                <h3 className="font-medium mb-3">Atividade por Período</h3>
                <div className="grid grid-cols-4 gap-4">
                  <Card>
                    <CardContent className="p-4 text-center">
                      <p className="text-2xl font-bold text-blue-600">{stats.total}</p>
                      <p className="text-sm text-gray-600">Total</p>
                    </CardContent>
                  </Card>
                  <Card>
                    <CardContent className="p-4 text-center">
                      <p className="text-2xl font-bold text-green-600">{stats.today}</p>
                      <p className="text-sm text-gray-600">Hoje</p>
                    </CardContent>
                  </Card>
                  <Card>
                    <CardContent className="p-4 text-center">
                      <p className="text-2xl font-bold text-purple-600">{stats.yesterday}</p>
                      <p className="text-sm text-gray-600">Ontem</p>
                    </CardContent>
                  </Card>
                  <Card>
                    <CardContent className="p-4 text-center">
                      <p className="text-2xl font-bold text-orange-600">{stats.thisWeek}</p>
                      <p className="text-sm text-gray-600">7 dias</p>
                    </CardContent>
                  </Card>
                </div>
              </div>

              {/* Estatísticas por status */}
              <div>
                <h3 className="font-medium mb-3">Distribuição por Status</h3>
                <div className="grid grid-cols-3 gap-4">
                  <Card>
                    <CardContent className="p-4 text-center">
                      <CheckCircle className="w-8 h-8 text-green-600 mx-auto mb-2" />
                      <p className="text-2xl font-bold text-green-600">{stats.byStatus.success}</p>
                      <p className="text-sm text-gray-600">Sucesso</p>
                    </CardContent>
                  </Card>
                  <Card>
                    <CardContent className="p-4 text-center">
                      <XCircle className="w-8 h-8 text-red-600 mx-auto mb-2" />
                      <p className="text-2xl font-bold text-red-600">{stats.byStatus.error}</p>
                      <p className="text-sm text-gray-600">Erro</p>
                    </CardContent>
                  </Card>
                  <Card>
                    <CardContent className="p-4 text-center">
                      <AlertTriangle className="w-8 h-8 text-yellow-600 mx-auto mb-2" />
                      <p className="text-2xl font-bold text-yellow-600">{stats.byStatus.warning}</p>
                      <p className="text-sm text-gray-600">Aviso</p>
                    </CardContent>
                  </Card>
                </div>
              </div>

              {/* Top ações */}
              <div>
                <h3 className="font-medium mb-3">Ações Mais Frequentes</h3>
                <div className="space-y-2">
                  {Object.entries(stats.byAction)
                    .sort(([,a], [,b]) => (b as number) - (a as number))
                    .slice(0, 10)
                    .map(([action, count]) => (
                      <div key={action} className="flex items-center justify-between p-2 bg-gray-50 rounded">
                        <div className="flex items-center">
                          {getActionIcon(action)}
                          <span className="ml-2 font-medium">{action}</span>
                        </div>
                        <Badge variant="outline">{count as number}</Badge>
                      </div>
                    ))
                  }
                </div>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

src/components/AdminUserManagement.tsx.content:
"use client";

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Avatar, AvatarImage, AvatarFallback } from '@/components/ui/avatar';
import { useUsers } from '@/lib/hooks';
import { User } from '@/lib/types';
import { 
  Users, 
  Search, 
  Filter, 
  Calendar,
  Mail,
  Phone,
  User as UserIcon,
  Crown,
  Shield,
  CheckCircle,
  XCircle,
  Clock,
  Target,
  Activity,
  Zap,
  TrendingUp,
  Heart,
  Eye,
  ChevronDown,
  ChevronUp,
  FileText
} from 'lucide-react';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';

interface AdminUserManagementProps {
  onViewUserLogs?: (userId: string, userName: string) => void;
  onUpgradeUser?: (userId: string, currentPlan: string) => void;
}

export function AdminUserManagement({ onViewUserLogs, onUpgradeUser }: AdminUserManagementProps) {
  const { users } = useUsers();
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedPlan, setSelectedPlan] = useState<string>('all');
  const [selectedStatus, setSelectedStatus] = useState<string>('all');
  const [sortBy, setSortBy] = useState<'name' | 'createdAt' | 'plan'>('createdAt');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');
  const [viewMode, setViewMode] = useState<'cards' | 'table'>('cards');
  const [expandedUser, setExpandedUser] = useState<string | null>(null);

  // Filtrar e ordenar usuários
  const filteredUsers = users
    .filter(user => {
      // Filtro por busca (nome ou email)
      const matchesSearch = searchTerm === '' || 
        user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        user.email.toLowerCase().includes(searchTerm.toLowerCase());

      // Filtro por plano
      const matchesPlan = selectedPlan === 'all' || 
        user.subscription?.plan === selectedPlan;

      // Filtro por status
      const matchesStatus = selectedStatus === 'all' || 
        (selectedStatus === 'active' && user.subscription?.status === 'active') ||
        (selectedStatus === 'inactive' && user.subscription?.status !== 'active') ||
        (selectedStatus === 'admin' && user.isAdmin) ||
        (selectedStatus === 'verified' && user.emailVerified) ||
        (selectedStatus === 'unverified' && !user.emailVerified);

      return matchesSearch && matchesPlan && matchesStatus;
    })
    .sort((a, b) => {
      let aValue: any, bValue: any;

      switch (sortBy) {
        case 'name':
          aValue = a.name.toLowerCase();
          bValue = b.name.toLowerCase();
          break;
        case 'createdAt':
          aValue = new Date(a.createdAt).getTime();
          bValue = new Date(b.createdAt).getTime();
          break;
        case 'plan':
          aValue = a.subscription?.plan || 'zzz'; // Colocar no final se não tiver plano
          bValue = b.subscription?.plan || 'zzz';
          break;
        default:
          return 0;
      }

      if (aValue < bValue) return sortOrder === 'asc' ? -1 : 1;
      if (aValue > bValue) return sortOrder === 'asc' ? 1 : -1;
      return 0;
    });

  // Função para obter cor do plano
  const getPlanColor = (plan?: string) => {
    switch (plan) {
      case 'starter': return 'bg-blue-100 text-blue-800';
      case 'standard': return 'bg-green-100 text-green-800';
      case 'premium': return 'bg-purple-100 text-purple-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  // Função para obter cor do status
  const getStatusColor = (status?: string) => {
    switch (status) {
      case 'active': return 'bg-green-100 text-green-800';
      case 'inactive': return 'bg-red-100 text-red-800';
      case 'cancelled': return 'bg-yellow-100 text-yellow-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  // Função para calcular uso percentual
  const getUsagePercentage = (used: number, limit: number | string) => {
    if (limit === 'unlimited') return 0;
    return Math.round((used / (limit as number)) * 100);
  };

  // Estatísticas gerais
  const totalUsers = users.length;
  const activeUsers = users.filter(u => u.subscription?.status === 'active').length;
  const adminUsers = users.filter(u => u.isAdmin).length;
  const verifiedUsers = users.filter(u => u.emailVerified).length;

  const toggleUserExpanded = (userId: string) => {
    setExpandedUser(expandedUser === userId ? null : userId);
  };

  // Função para lidar com visualização de logs do usuário
  const handleViewUserLogs = (userId: string, userName: string) => {
    if (onViewUserLogs) {
      onViewUserLogs(userId, userName);
    }
  };

  // Função para lidar com upgrade de usuário
  const handleUpgradeUser = (userId: string, currentPlan: string) => {
    if (onUpgradeUser) {
      onUpgradeUser(userId, currentPlan);
    }
  };

  // Verificar se usuário pode fazer upgrade
  const canUpgrade = (plan?: string) => {
    return plan === 'starter' || plan === 'standard';
  };

  // Obter próximo plano
  const getNextPlan = (currentPlan: string) => {
    switch (currentPlan) {
      case 'starter': return 'standard';
      case 'standard': return 'premium';
      default: return null;
    }
  };

  const renderUserCard = (user: User) => (
    <Card key={user.id} className="relative hover:shadow-md transition-shadow">
      <CardHeader className="pb-3">
        <div className="flex items-center space-x-3">
          <Avatar>
            <AvatarFallback className={user.isAdmin ? 'bg-yellow-100 text-yellow-800' : 'bg-gray-100'}>
              {user.isAdmin ? <Shield className="w-4 h-4" /> : user.name.charAt(0).toUpperCase()}
            </AvatarFallback>
          </Avatar>
          <div className="flex-1 min-w-0">
            <h3 className="font-medium text-gray-900 truncate">{user.name}</h3>
            <p className="text-sm text-gray-500 truncate flex items-center">
              <Mail className="w-3 h-3 mr-1" />
              {user.email}
            </p>
          </div>
          <div className="flex flex-col items-end space-y-1">
            {user.isAdmin && (
              <Badge className="bg-yellow-100 text-yellow-800">
                <Crown className="w-3 h-3 mr-1" />
                Admin
              </Badge>
            )}
            {user.subscription && (
              <div className="flex items-center space-x-1">
                <Badge className={getPlanColor(user.subscription.plan)}>
                  {user.subscription.plan}
                </Badge>
                {canUpgrade(user.subscription.plan) && (
                  <Button
                    size="sm"
                    variant="outline"
                    className="h-6 px-2 text-xs"
                    onClick={() => handleUpgradeUser(user.id, user.subscription?.plan || '')}
                  >
                    <TrendingUp className="w-3 h-3 mr-1" />
                    Upgrade
                  </Button>
                )}
              </div>
            )}
          </div>
        </div>
      </CardHeader>

      <CardContent className="pt-0">
        <div className="space-y-2">
          {/* Status da conta */}
          <div className="flex items-center justify-between text-sm">
            <span className="text-gray-600">Status:</span>
            <div className="flex items-center space-x-2">
              {user.emailVerified ? (
                <Badge className="bg-green-100 text-green-800">
                  <CheckCircle className="w-3 h-3 mr-1" />
                  Verificado
                </Badge>
              ) : (
                <Badge className="bg-red-100 text-red-800">
                  <XCircle className="w-3 h-3 mr-1" />
                  Não verificado
                </Badge>
              )}
              {user.subscription && (
                <Badge className={getStatusColor(user.subscription.status)}>
                  {user.subscription.status === 'active' ? 'Ativo' : 'Inativo'}
                </Badge>
              )}
            </div>
          </div>

          {/* Data de criação */}
          <div className="flex items-center justify-between text-sm">
            <span className="text-gray-600">Criado em:</span>
            <span className="text-gray-900 flex items-center">
              <Calendar className="w-3 h-3 mr-1" />
              {format(new Date(user.createdAt), 'dd/MM/yyyy', { locale: ptBR })}
            </span>
          </div>

          {/* Informações da assinatura */}
          {user.subscription && (
            <>
              <div className="flex items-center justify-between text-sm">
                <span className="text-gray-600">Assinatura:</span>
                <span className="text-gray-900">
                  {format(new Date(user.subscription.startDate), 'dd/MM/yyyy', { locale: ptBR })} - {format(new Date(user.subscription.endDate), 'dd/MM/yyyy', { locale: ptBR })}
                </span>
              </div>

              {/* Uso mensal */}
              <div className="space-y-1">
                <div className="flex items-center justify-between text-xs text-gray-600">
                  <span>Dietas:</span>
                  <span>{user.subscription.dietsUsedThisMonth} usadas</span>
                </div>
                <div className="flex items-center justify-between text-xs text-gray-600">
                  <span>Treinos:</span>
                  <span>{user.subscription.workoutsUsedThisMonth} usados</span>
                </div>
                <div className="flex items-center justify-between text-xs text-gray-600">
                  <span>Análises:</span>
                  <span>{user.subscription.bodyAnalysesUsedThisMonth} usadas</span>
                </div>
              </div>
            </>
          )}

          {/* Botões de ação */}
          <div className="flex items-center justify-between pt-2">
            {/* Botão para expandir detalhes */}
            <Button
              variant="ghost"
              size="sm"
              onClick={() => toggleUserExpanded(user.id)}
            >
              {expandedUser === user.id ? (
                <>
                  <ChevronUp className="w-4 h-4 mr-1" />
                  Menos detalhes
                </>
              ) : (
                <>
                  <ChevronDown className="w-4 h-4 mr-1" />
                  Ver detalhes
                </>
              )}
            </Button>

            {/* Botão para ver logs */}
            <Button
              size="sm"
              variant="outline"
              onClick={() => handleViewUserLogs(user.id, user.name)}
            >
              <FileText className="w-4 h-4 mr-1" />
              Ver Logs
            </Button>
          </div>

          {/* Detalhes expandidos */}
          {expandedUser === user.id && user.profile && (
            <div className="mt-3 p-3 bg-gray-50 rounded-lg space-y-2">
              <h4 className="font-medium text-gray-900 mb-2">Perfil do Usuário</h4>

              <div className="grid grid-cols-2 gap-2 text-sm">
                <div>
                  <span className="text-gray-600">Idade:</span>
                  <p className="font-medium">{user.profile.age} anos</p>
                </div>
                <div>
                  <span className="text-gray-600">Gênero:</span>
                  <p className="font-medium">{user.profile.gender}</p>
                </div>
                <div>
                  <span className="text-gray-600">Altura:</span>
                  <p className="font-medium">{user.profile.height} cm</p>
                </div>
                <div>
                  <span className="text-gray-600">Peso:</span>
                  <p className="font-medium">{user.profile.weight} kg</p>
                </div>
              </div>

              <div className="text-sm">
                <span className="text-gray-600">Objetivo:</span>
                <p className="font-medium">{user.profile.goal.replace('-', ' ')}</p>
              </div>

              <div className="text-sm">
                <span className="text-gray-600">Nível de atividade:</span>
                <p className="font-medium">{user.profile.activityLevel}</p>
              </div>

              {user.profile.preferredMuscleGroups.length > 0 && (
                <div className="text-sm">
                  <span className="text-gray-600">Grupos musculares preferidos:</span>
                  <div className="flex flex-wrap gap-1 mt-1">
                    {user.profile.preferredMuscleGroups.map((group, index) => (
                      <Badge key={index} variant="outline" className="text-xs">
                        {group}
                      </Badge>
                    ))}
                  </div>
                </div>
              )}

              {user.profile.foodRestrictions.length > 0 && (
                <div className="text-sm">
                  <span className="text-gray-600">Restrições alimentares:</span>
                  <div className="flex flex-wrap gap-1 mt-1">
                    {user.profile.foodRestrictions.map((restriction, index) => (
                      <Badge key={index} variant="outline" className="text-xs bg-red-50 text-red-700">
                        {restriction}
                      </Badge>
                    ))}
                  </div>
                </div>
              )}

              {user.profile.foodPreferences.length > 0 && (
                <div className="text-sm">
                  <span className="text-gray-600">Preferências alimentares:</span>
                  <div className="flex flex-wrap gap-1 mt-1">
                    {user.profile.foodPreferences.map((preference, index) => (
                      <Badge key={index} variant="outline" className="text-xs bg-green-50 text-green-700">
                        {preference}
                      </Badge>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );

  return (
    <div className="space-y-6">
      {/* Header com estatísticas */}
      <div>
        <h2 className="text-2xl font-bold text-gray-900 mb-4 flex items-center">
          <Users className="w-6 h-6 mr-2" />
          Gerenciamento de Usuários
        </h2>

        {/* Cards de estatísticas */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
          <Card>
            <CardContent className="p-4">
              <div className="flex items-center">
                <Users className="w-8 h-8 text-blue-600" />
                <div className="ml-3">
                  <p className="text-sm font-medium text-gray-500">Total</p>
                  <p className="text-2xl font-bold text-gray-900">{totalUsers}</p>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-4">
              <div className="flex items-center">
                <Activity className="w-8 h-8 text-green-600" />
                <div className="ml-3">
                  <p className="text-sm font-medium text-gray-500">Ativos</p>
                  <p className="text-2xl font-bold text-gray-900">{activeUsers}</p>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-4">
              <div className="flex items-center">
                <Shield className="w-8 h-8 text-yellow-600" />
                <div className="ml-3">
                  <p className="text-sm font-medium text-gray-500">Admins</p>
                  <p className="text-2xl font-bold text-gray-900">{adminUsers}</p>
                </div>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="p-4">
              <div className="flex items-center">
                <CheckCircle className="w-8 h-8 text-purple-600" />
                <div className="ml-3">
                  <p className="text-sm font-medium text-gray-500">Verificados</p>
                  <p className="text-2xl font-bold text-gray-900">{verifiedUsers}</p>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>

      {/* Filtros e busca */}
      <Card>
        <CardContent className="p-4">
          <div className="flex flex-col md:flex-row md:items-center space-y-4 md:space-y-0 md:space-x-4">
            {/* Busca */}
            <div className="flex-1">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                <Input
                  placeholder="Buscar por nome ou email..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10"
                />
              </div>
            </div>

            {/* Filtros */}
            <div className="flex space-x-2">
              <Select value={selectedPlan} onValueChange={setSelectedPlan}>
                <SelectTrigger className="w-32">
                  <SelectValue placeholder="Plano" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos</SelectItem>
                  <SelectItem value="starter">Starter</SelectItem>
                  <SelectItem value="standard">Standard</SelectItem>
                  <SelectItem value="premium">Premium</SelectItem>
                </SelectContent>
              </Select>

              <Select value={selectedStatus} onValueChange={setSelectedStatus}>
                <SelectTrigger className="w-32">
                  <SelectValue placeholder="Status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos</SelectItem>
                  <SelectItem value="active">Ativo</SelectItem>
                  <SelectItem value="inactive">Inativo</SelectItem>
                  <SelectItem value="admin">Admins</SelectItem>
                  <SelectItem value="verified">Verificado</SelectItem>
                  <SelectItem value="unverified">Não verificado</SelectItem>
                </SelectContent>
              </Select>

              <Select value={sortBy} onValueChange={(value: any) => setSortBy(value)}>
                <SelectTrigger className="w-32">
                  <SelectValue placeholder="Ordenar" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="createdAt">Data</SelectItem>
                  <SelectItem value="name">Nome</SelectItem>
                  <SelectItem value="plan">Plano</SelectItem>
                </SelectContent>
              </Select>

              <Button
                variant="outline"
                size="sm"
                onClick={() => setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc')}
              >
                {sortOrder === 'asc' ? <TrendingUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Lista de usuários */}
      <div>
        <div className="flex items-center justify-between mb-4">
          <p className="text-sm text-gray-600">
            Mostrando {filteredUsers.length} de {totalUsers} usuários
          </p>
        </div>

        {filteredUsers.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {filteredUsers.map(renderUserCard)}
          </div>
        ) : (
          <Card>
            <CardContent className="p-8 text-center">
              <Users className="w-12 h-12 text-gray-400 mx-auto mb-4" />
              <h3 className="text-lg font-medium text-gray-900 mb-2">Nenhum usuário encontrado</h3>
              <p className="text-gray-500">
                Tente ajustar os filtros ou termo de busca.
              </p>
            </CardContent>
          </Card>
        )}
      </div>
    </div>
  );
}

src/components/ForgotPassword.tsx.content:
"use client";

import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { ArrowLeft, Mail, Shield, CheckCircle } from 'lucide-react';
import { usePasswordReset } from '@/lib/hooks';
import { sendEmail } from '@/utils/replitmail';

interface ForgotPasswordProps {
  onBack: () => void;
}

export function ForgotPassword({ onBack }: ForgotPasswordProps) {
  const [email, setEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');

  const { checkRateLimit, incrementAttempt, createResetToken, emailExists } = usePasswordReset();

  const validateEmail = (email: string): boolean => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      // Validar formato do email
      if (!validateEmail(email)) {
        setError('Por favor, digite um email válido');
        setLoading(false);
        return;
      }

      // Verificar rate limiting
      if (!checkRateLimit(email)) {
        setError('Muitas tentativas. Tente novamente em 1 hora.');
        setLoading(false);
        return;
      }

      // Incrementar tentativa (independente de sucesso)
      incrementAttempt(email);

      // SEMPRE mostrar mensagem de sucesso para não revelar se email existe
      // Mas só enviar email se realmente existir
      if (emailExists(email)) {
        // Gerar token seguro
        const token = createResetToken(email);

        // URL completa para reset (usar window.location.origin)
        const resetUrl = `${window.location.origin}/?resetToken=${token}&email=${encodeURIComponent(email)}`;

        // HTML formatado para o email
        const htmlContent = `
          <!DOCTYPE html>
          <html>
          <head>
            <meta charset="utf-8">
            <style>
              body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; }
              .header { background: linear-gradient(135deg, #2563eb, #1d4ed8); color: white; padding: 20px; text-align: center; }
              .content { padding: 30px 20px; background: #f8fafc; }
              .button { display: inline-block; background: #2563eb; color: white; padding: 12px 24px; text-decoration: none; border-radius: 6px; margin: 20px 0; }
              .warning { background: #fef3c7; border-left: 4px solid #f59e0b; padding: 15px; margin: 20px 0; }
              .footer { background: #1f2937; color: #9ca3af; padding: 20px; text-align: center; font-size: 12px; }
            </style>
          </head>
          <body>
            <div class="header">
              <h1>🏋️ FitAI Coach</h1>
              <p>Redefinir sua senha</p>
            </div>

            <div class="content">
              <h2>Olá!</h2>
              <p>Você solicitou a redefinição da sua senha do FitAI Coach. Para continuar, clique no botão abaixo:</p>

              <center>
                <a href="${resetUrl}" class="button">🔒 Redefinir Senha</a>
              </center>

              <p>Ou copie e cole este link no seu navegador:</p>
              <p style="word-break: break-all; background: #e2e8f0; padding: 10px; border-radius: 4px;">${resetUrl}</p>

              <div class="warning">
                <h3>⚠️ Importante:</h3>
                <ul>
                  <li>Este link expira em <strong>1 hora</strong></li>
                  <li>Use apenas se você solicitou esta redefinição</li>
                  <li>Nunca compartilhe este link com outras pessoas</li>
                  <li>Se você não solicitou, ignore este email</li>
                </ul>
              </div>

              <p>Se você não conseguir clicar no botão, copie o link completo e cole no navegador.</p>
            </div>

            <div class="footer">
              <p>© 2025 FitAI Coach - Seu personal trainer com IA</p>
              <p>Este é um email automático, não responda.</p>
            </div>
          </body>
          </html>
        `;

        const textContent = `
FitAI Coach - Redefinir senha

Olá!

Você solicitou a redefinição da sua senha do FitAI Coach.

Para redefinir sua senha, acesse o link abaixo:
${resetUrl}

IMPORTANTE:
- Este link expira em 1 hora
- Use apenas se você solicitou esta redefinição
- Nunca compartilhe este link com outras pessoas
- Se você não solicitou, ignore este email

Se você não conseguir clicar no link, copie e cole no seu navegador.

© 2025 FitAI Coach - Seu personal trainer com IA
        `;

        // Enviar email usando Replit Mail
        await sendEmail({
          to: email,
          subject: 'FitAI Coach - Redefinir sua senha',
          html: htmlContent,
          text: textContent
        });
      }

      // SEMPRE mostrar mensagem de sucesso (segurança)
      setSuccess(true);

    } catch (error) {
      console.error('Erro ao enviar email de recuperação:', error);
      setError('Erro interno. Tente novamente em alguns minutos.');
    } finally {
      setLoading(false);
    }
  };

  if (success) {
    return (
      <div className="ios-main-scroll bg-gradient-to-br from-blue-50 to-indigo-100 dark:from-blue-950 dark:to-indigo-950 flex items-center justify-center safe-area">
        <div className="w-full max-w-md px-3 md:px-0 ios-content-scroll">
          <Card className="shadow-xl border-green-200 dark:border-green-800">
            <CardHeader className="text-center p-4 sm:p-6">
              <CardTitle className="flex items-center justify-center gap-2 text-green-700 dark:text-green-300 text-lg sm:text-xl">
                <CheckCircle className="w-6 h-6" />
                Email enviado!
              </CardTitle>
            </CardHeader>
            <CardContent className="p-4 sm:p-6 space-y-4">
              <div className="text-center">
                <div className="p-4 bg-green-50 dark:bg-green-950 rounded-lg mb-4">
                  <Mail className="w-12 h-12 text-green-600 mx-auto mb-3" />
                  <h3 className="font-semibold text-green-800 dark:text-green-200 mb-2">
                    Verifique seu email
                  </h3>
                  <p className="text-sm text-green-700 dark:text-green-300">
                    Se o email <strong>{email}</strong> estiver cadastrado, você receberá um link para redefinir sua senha.
                  </p>
                </div>

                <div className="p-3 bg-blue-50 dark:bg-blue-950 rounded-lg text-xs text-blue-700 dark:text-blue-300">
                  <Shield className="w-4 h-4 inline mr-2" />
                  <strong>Segurança:</strong> O link expira em 1 hora
                </div>
              </div>

              <div className="space-y-3">
                <Button 
                  onClick={onBack}
                  variant="outline"
                  className="w-full touch-target"
                >
                  <ArrowLeft className="w-4 h-4 mr-2" />
                  Voltar ao login
                </Button>

                <Button
                  onClick={() => {
                    setSuccess(false);
                    setEmail('');
                    setError('');
                  }}
                  variant="ghost"
                  className="w-full text-sm text-blue-600 hover:text-blue-700 touch-target"
                >
                  Tentar outro email
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    );
  }

  return (
    <div className="ios-main-scroll bg-gradient-to-br from-blue-50 to-indigo-100 dark:from-blue-950 dark:to-indigo-950 flex items-center justify-center safe-area">
      <div className="w-full max-w-md px-3 md:px-0 ios-content-scroll">
        <Card className="shadow-xl border-blue-100 dark:border-blue-800">
          <CardHeader className="text-center p-4 sm:p-6">
            <CardTitle className="flex items-center justify-center gap-2 text-blue-900 dark:text-blue-100 text-lg sm:text-xl">
              <Shield className="w-5 h-5" />
              Recuperar senha
            </CardTitle>
            <p className="text-sm text-blue-700 dark:text-blue-300 mt-2">
              Digite seu email para receber o link de recuperação
            </p>
          </CardHeader>
          <CardContent className="p-4 sm:p-6">
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="email" className="text-blue-800 dark:text-blue-200">
                  Email cadastrado
                </Label>
                <Input
                  id="email"
                  type="email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="seu@email.com"
                  required
                  disabled={loading}
                  className="border-blue-200 dark:border-blue-700 focus:ring-blue-500 touch-target text-base"
                />
              </div>

              {error && (
                <div className="text-red-600 text-sm bg-red-50 dark:bg-red-950 p-3 rounded border border-red-200 dark:border-red-800">
                  {error}
                </div>
              )}

              <Button 
                type="submit" 
                disabled={loading || !email}
                className="w-full bg-blue-600 hover:bg-blue-700 text-white disabled:opacity-50 touch-target"
              >
                {loading ? (
                  <>
                    <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin mr-2" />
                    Enviando...
                  </>
                ) : (
                  <>
                    <Mail className="w-4 h-4 mr-2" />
                    Enviar link de recuperação
                  </>
                )}
              </Button>
            </form>

            <div className="mt-6 space-y-3">
              <Button
                variant="outline"
                onClick={onBack}
                className="w-full border-blue-200 text-blue-600 hover:bg-blue-50 touch-target"
              >
                <ArrowLeft className="w-4 h-4 mr-2" />
                Voltar ao login
              </Button>
            </div>

            {/* Informações de segurança */}
            <div className="mt-6 p-3 bg-blue-50 dark:bg-blue-950 rounded-lg text-xs text-blue-700 dark:text-blue-300">
              <h4 className="font-semibold mb-2 flex items-center">
                <Shield className="w-4 h-4 mr-1" />
                Segurança
              </h4>
              <ul className="space-y-1 list-disc list-inside">
                <li>Link válido por apenas 1 hora</li>
                <li>Máximo de 3 tentativas por hora</li>
                <li>Não revelamos se o email existe</li>
              </ul>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

